template:
% 参数由系统自动注入：\def\base{2} \def\showinverse{0} \def\showfixed{1} \def\showpoint{0} \def\px{2} \def\labelp{P}
% 点 P 纵坐标 log_a(px)=ln(px)/ln(a)（pgfmath 的 ln 为自然对数）
\pgfmathsetmacro{\py}{ln(\px)/ln(\base)}
% y 视图对称，纳入点 P
\pgfmathsetmacro{\v}{max(2.5, abs(\py)+0.8)}
\pgfmathtruncatemacro{\ytop}{ceil(\v)}
\pgfmathtruncatemacro{\ybottom}{-\ytop}
% 曲线与上下边框交点的 x 坐标
\pgfmathsetmacro{\xatop}{pow(\base,\ytop+0.3)}
\pgfmathsetmacro{\xabot}{pow(\base,\ybottom-0.3)}
\pgfmathsetmacro{\xhiraw}{max(\xatop,\xabot)}
\pgfmathsetmacro{\xloraw}{min(\xatop,\xabot)}
% 视图以特征点为准，对数增长缓慢，曲线从画框右侧自然走出
\pgfmathsetmacro{\xfeat}{max(4.0, \px+1.0)}
\pgfmathtruncatemacro{\xright}{ceil(\xfeat)+1}
\pgfmathtruncatemacro{\xleft}{-2}
\pgfmathsetmacro{\dlo}{max(\xloraw,0.01)}
\pgfmathsetmacro{\dhi}{min(\xhiraw,\xright)}
\pgfmathsetmacro{\xrange}{\xright-\xleft}
\pgfmathsetmacro{\yrange}{\ytop-\ybottom}
\pgfmathsetmacro{\figscale}{6.5/max(\xrange,\yrange)}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系（y 轴即渐近线）=====
  \draw[->, thick] (\xleft-0.5,0) -- (\xright+0.6,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$}; % ===== 反函数：y=a^x 虚线 + 对称轴 y=x =====
  \ifnum\showinverse>0
    \pgfmathsetmacro{\xe}{ln(\ytop+0.3)/ln(\base)}
    \ifdim\base pt>1pt
      \pgfmathsetmacro{\elo}{\xleft}
      \pgfmathsetmacro{\ehi}{min(\xright,\xe)}
    \else
      \pgfmathsetmacro{\elo}{max(\xleft,\xe)}
      \pgfmathsetmacro{\ehi}{\xright}
    \fi
    \draw[dashed, gray, thick, domain=\elo:\ehi, samples=80, smooth] plot (\x, {pow(\base,\x)});
    \pgfmathsetmacro{\dt}{min(\xright,\ytop)}
    \draw[dashed, gray!60] (-2,-2) -- (\dt,\dt);
    \node[above left, font=\tiny, gray] at (\dt-0.3,\dt-0.6) {$y=x$};
  \fi
  % ===== 主曲线 y=log_a x =====
  \draw[thick, domain=\dlo:\dhi, samples=120, smooth] plot (\x, {ln(\x)/ln(\base)});
  \ifdim\base pt>1pt
    \node[above right, font=\tiny] at (\dhi-0.3,\ytop-0.6) {$y=\log_a x$};
  \else
    \node[above right, font=\tiny] at (\dlo+0.2,\ytop-0.6) {$y=\log_a x$};
  \fi
  % ===== 定点 (1,0) =====
  \ifnum\showfixed>0
    \fill (1,0) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (1,0) {$(1,0)$};
  \fi
  % ===== 曲线上点 P =====
  \ifnum\showpoint>0
    \fill (\px,\py) circle [radius=\dotr pt];
    \node[above right, font=\tiny] at (\px,\py) {$\labelp$};
  \fi
\end{tikzpicture}
